#!/usr/bin/env bash
# Host one Gemma-2-2B server with every generated T2L LoRA module on the target GPU.
#
# vLLM's --lora-modules takes one module per flag (duplicates are rejected), so the
# module list lives in artifacts/serve_config.yaml, regenerated by scripts/build_serve_config.py.
set -euo pipefail

cd "$(dirname "$0")/.."
export CUDA_VISIBLE_DEVICES="${CUDA_VISIBLE_DEVICES:-6}"
export VLLM_USE_FLASHINFER_SAMPLER=0

CONFIG="${CONFIG:-artifacts/serve_config.yaml}"
if [[ ! -f "$CONFIG" ]]; then
  uv run python scripts/build_serve_config.py
fi

exec .venv-serve/bin/vllm serve --config "$CONFIG"
